fn child_follower_3_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.lines_as("Lewei", args!["Shushh!", "Be quiet."])?;
    ctx.next()?;
    ctx.lines_as("Lewei", args!["......", "........."])?;
    ctx.next()?;
    ctx.lines_as(
        "Lewei",
        args!["Go away! If someone!", "sees you, I'm gonna", "get caught, you jerk!"],
    )?;
    ctx.next()?;
    if Val::from(runtime::select_values(ctx, &[Val::from("What are you doing?:Alright.")])?) == 1 {
        ctx.lines_as(
            "Lewei",
            args![
                "Hellooo~?",
                "Can't you see?",
                "It's called Hide-and-",
                "Go-Seek. Gee whiz!",
                "Hurry, get away!"
            ],
        )?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
    ctx.lines_as("Lewei", args!["Hurry, and get", "outta here!"])?;
    ctx.close_window()?;
    return Err(Stop::End);
}

